private int getChunk() {
    if (sChunk != 0) {
        return sChunk;
    }
    final int WINDOW_SIZE_KB = 2048;
    int sCursorWindowSize = WINDOW_SIZE_KB * 1024;

    // reduce the actual size a little bit.
