public void setConf(JSONObject conf) {
        // Anki sometimes set sortBackward to 0/1 instead of
        // False/True. This should be repaired before setting mConf;
        // otherwise this may save a faulty value in mConf, and if
        // it's done just before the value is read, this may lead to
        // bug #5523. This bug should occur only for people using anki
        // prior to version 2.16 and has been corrected with
        // dae/anki#347
        Upgrade.upgradeJSONIfNecessary(this, conf, "sortBackwards", false);
        mConf = conf;
    }

public LanguagesListerGlosbe() {
        final String [] languages ={"eng", "deu", "jpn", "fra", "spa", "pol", "ita", "rus",
            "ces", "zho", "nld", "por", "swe", "hrv", "hin", "hun", "vie", "ara", "tur"};
        // Java Locale uses ISO 639-2 rather than 639-3 so we currently only support the subset of
        // the languages on Glosbe which are in ISO 639-2. "Chinese Mandarin" ("cmn") for example
        // is not supported, but "Chinese" ("zho") is.
        for (String l : languages) {
            Locale locale = new Locale(l);
            addLanguage(locale.getDisplayLanguage(), locale.getISO3Language());
        }
    }

