public KeyPair loadKeyPair(AccountID account)
{
    if (account == null)
        return null;

    String accountID = account.getAccountUniqueID();

    // Load Private Key.
    byte[] b64PrivKey =
        this.configurator.getPropertyBytes(accountID + ".privateKey");
    if (b64PrivKey == null)
        return null;

    PKCS8EncodedKeySpec privateKeySpec =
        new PKCS8EncodedKeySpec(b64PrivKey);

    // Load Public Key.
    byte[] b64PubKey =
        this.configurator.getPropertyBytes(accountID + ".publicKey");
    if (b64PubKey == null)
        return null;

    X509EncodedKeySpec publicKeySpec = new X509EncodedKeySpec(b64PubKey);

    PublicKey publicKey;
    PrivateKey privateKey;

    // Generate KeyPair.
    KeyFactory keyFactory;
    try
    {
        keyFactory = KeyFactory.getInstance("DSA");
        publicKey = keyFactory.generatePublic(publicKeySpec);
        privateKey = keyFactory.generatePrivate(privateKeySpec);
    }
    catch (NoSuchAlgorithmException e)
    {
        e.printStackTrace();
        return null;
    }
    catch (InvalidKeySpecException e)
    {
        e.printStackTrace();
        return null;
    }

    return new KeyPair(publicKey, privateKey);
}

