public StatusSelector(
        ProtocolProviderService provider,
        OperationSetPresence presence,
        boolean swing)
{
    this.provider = provider;
    this.presence = presence;

    /* the parent item */
    {
        String text = provider.getAccountID().getDisplayName();
        if (swing)
        {
            JMenu menu = new JMenu(text);
            byte[] icBytes = presence.getPresenceStatus().getStatusIcon();
            if(icBytes != null)
                menu.setIcon(new ImageIcon(icBytes));

            this.menu = menu;
        }
        else
        {
            this.menu = new Menu(text);
        }
    }

    /* the submenu itself */

    PresenceStatus offlineStatus = null;
    Iterator<PresenceStatus> statusIterator
        = this.presence.getSupportedStatusSet();

    while (statusIterator.hasNext())
    {
        PresenceStatus status = statusIterator.next();

        // if connectivity less then 1, this is offline one
        if(status.getStatus() < 1)
            offlineStatus = status;

        String text = status.getStatusName();

        if (menu instanceof Container)
        {
            JCheckBoxMenuItem item = new JCheckBoxMenuItem(text);

            byte[] icBytes = status.getStatusIcon();
            if(icBytes != null)
                item.setIcon(new ImageIcon(icBytes));

            item.addActionListener(this);

            ((Container) menu).add(item);
        }
        else
        {
            CheckboxMenuItem item = new CheckboxMenuItem(text);
            item.addItemListener(this);
            ((Menu) menu).add(item);
        }
    }

    addSeparator();

    StatusSubMenu.addMenuItem(menu, new StatusMessageMenu(provider, swing)
        .getMenu());

    if(offlineStatus != null)
        updateStatus(offlineStatus);
}

public Iterator<GenericDetail> requestAllDetailsForContact(
        final Contact contact, DetailsResponseListener listener)
{
    synchronized(listenersForDetails)
    {
        List<DetailsResponseListener> ls =
            listenersForDetails.get(contact.getAddress());

        boolean isFirst = false;
        if(ls == null)
        {
            ls = new ArrayList<DetailsResponseListener>();
            isFirst = true;
            listenersForDetails.put(contact.getAddress(), ls);
        }

        if(!ls.contains(listener))
            ls.add(listener);

        // there is already scheduled retrieve, will deliver at listener.
        if(!isFirst)
            return null;
    }

    return null;
}

public Iterator<GenericDetail> requestAllDetailsForContact(
        final Contact contact, DetailsResponseListener listener)
{
    if (!(contact instanceof ContactJabberImpl))
    {
        return null;
    }

    List<GenericDetail> res =
        infoRetreiver.getCachedContactDetails(((ContactJabberImpl) contact)
            .getAddressAsJid().asEntityBareJidOrThrow());

    if(res != null)
    {
        return res.iterator();
    }

    synchronized(listenersForDetails)
    {
        List<DetailsResponseListener> ls =
            listenersForDetails.get(contact.getAddress());

        boolean isFirst = false;
        if(ls == null)
        {
            ls = new ArrayList<DetailsResponseListener>();
            isFirst = true;
            listenersForDetails.put(contact.getAddress(), ls);
        }

        if(!ls.contains(listener))
            ls.add(listener);

        // there is already scheduled retrieve, will deliver at listener.
        if(!isFirst)
            return null;
    }

    new Thread(new Runnable()
    {
        public void run()
        {
            List<GenericDetail> result =
                infoRetreiver.retrieveDetails(((ContactJabberImpl) contact)
                    .getAddressAsJid()
                    .asEntityBareJidOrThrow());

            List<DetailsResponseListener> listeners;

            synchronized(listenersForDetails)
            {
                listeners =
                    listenersForDetails.remove(contact.getAddress());
            }

            if(listeners == null || result == null)
                return;

            for(DetailsResponseListener l : listeners)
            {
                try
                {
                    l.detailsRetrieved(result.iterator());
                }
                catch(Throwable t)
                {
                    logger.error(
                        "Error delivering for retrieved details", t);
                }
            }
        }
    }, getClass().getName() + ".RetrieveDetails").start();

    // return null as there is no cache and we will try to retrieve
    return null;
}

public void testAccountUninstallationPersistence()
        throws Exception
    {
        Bundle providerBundle = SipSlickFixture.providerBundle;

        providerBundle.stop();

        assertTrue("Couldn't stop the protocol provider bundle. State was "
                   + providerBundle.getState()
                   ,    Bundle.ACTIVE   != providerBundle.getState()
                     && Bundle.STOPPING != providerBundle.getState());

        providerBundle.uninstall();

        assertEquals("Couldn't stop the protocol provider bundle."
                     , Bundle.UNINSTALLED, providerBundle.getState());

        //Now reinstall the bundle and restart the provider
        providerBundle
            = SipSlickFixture.bc.installBundle(providerBundle.getLocation());

        assertEquals("Couldn't re-install protocol provider bundle."
                     , Bundle.INSTALLED, providerBundle.getState());

        AccountManagerUtils.startBundleAndWaitStoredAccountsLoaded(
            SipSlickFixture.bc, providerBundle, ProtocolNames.SIP);
        assertEquals("Couldn't re-start protocol provider bundle."
                     , Bundle.ACTIVE, providerBundle.getState());


        //verify that the provider is not reinstalled
        ServiceReference[] sipProviderRefs = null;
        try
        {
            sipProviderRefs = SipSlickFixture.bc.getServiceReferences(
                ProtocolProviderService.class.getName(),
                "(" + ProtocolProviderFactory.PROTOCOL
                    + "=" +ProtocolNames.SIP + ")");
        }
        catch (InvalidSyntaxException ex)
        {
            fail("We apparently got our filter wrong " + ex.getMessage());
        }

        //make sure we didn't retrieve a service
        assertTrue("A SIP Protocol Provider Service was still regged as an "
                      +"osgi service after it was explicitly uninstalled"
                      ,sipProviderRefs == null || sipProviderRefs.length == 0);

        //and a nasty hack at the end - delete the configuration file so that
        //we get a fresh start on next run.
        ServiceReference confReference
            = SipSlickFixture.bc.getServiceReference(
                ConfigurationService.class.getName());
        ConfigurationService configurationService
            = (ConfigurationService) SipSlickFixture.bc.getService(confReference);

        configurationService.purgeStoredConfiguration();
    }
}

