  int oldCapacity = oldTable.length;
  @SuppressWarnings("unchecked") // Arrays and generics don't get along.
  Node<K, V>[] newTable = new Node[oldCapacity * 2];
}

static <K, V> Node<K, V>[] doubleCapacity(Node<K, V>[] oldTable) {
  int oldCapacity = oldTable.length;
  AvlIterator<K, V> iterator = new AvlIterator<>();

  for (int i = 0; i < oldCapacity; i++) {
    Node<K, V> root = oldTable[i];
    if (root == null) {
      continue;
    }

    // Split each tree into two trees.
    iterator.reset(root);
    int leftSize = 0;
    int rightSize = 0;
    for (Node<K, V> node; (node = iterator.next()) != null; ) {
      if ((node.hash & oldCapacity) == 0) {
        leftSize++;
      } else {
        rightSize++;
      }
    }
  }
}

static <K, V> Node<K, V>[] doubleCapacity(Node<K, V>[] oldTable) {
  int oldCapacity = oldTable.length;
  AvlIterator<K, V> iterator = new AvlIterator<>();

  for (int i = 0; i < oldCapacity; i++) {
    Node<K, V> root = oldTable[i];
    if (root == null) {
      continue;
    }

    // Compute the sizes of the left and right trees.
    iterator.reset(root);
    int leftSize = 0;
    int rightSize = 0;
    for (Node<K, V> node; (node = iterator.next()) != null; ) {
      if ((node.hash & oldCapacity) == 0) {
        leftSize++;
      } else {
        rightSize++;
      }
    }
  }
}

static <K, V> Node<K, V>[] doubleCapacity(Node<K, V>[] oldTable) {
  int oldCapacity = oldTable.length;
  AvlIterator<K, V> iterator = new AvlIterator<>();
  AvlBuilder<K, V> leftBuilder = new AvlBuilder<>();
  AvlBuilder<K, V> rightBuilder = new AvlBuilder<>();

  for (int i = 0; i < oldCapacity; i++) {
    Node<K, V> root = oldTable[i];
    if (root == null) {
      continue;
    }

    int leftSize = 0;
    int rightSize = 0;
    for (Node<K, V> node; (node = iterator.next()) != null; ) {
      if ((node.hash & oldCapacity) == 0) {
        leftSize++;
      } else {
        rightSize++;
      }
    }

    // Split the tree into two.
    leftBuilder.reset(leftSize);
    rightBuilder.reset(rightSize);
    iterator.reset(root);
    for (Node<K, V> node; (node = iterator.next()) != null; ) {
      if ((node.hash & oldCapacity) == 0) {
        leftBuilder.add(node);
      } else {
        rightBuilder.add(node);
      }
    }
  }
}

static <K, V> Node<K, V>[] doubleCapacity(Node<K, V>[] oldTable) {
  int oldCapacity = oldTable.length;
  @SuppressWarnings("unchecked")
  Node<K, V>[] newTable = new Node[oldCapacity * 2];
  AvlBuilder<K, V> leftBuilder = new AvlBuilder<>();
  AvlBuilder<K, V> rightBuilder = new AvlBuilder<>();

  for (int i = 0; i < oldCapacity; i++) {
    int leftSize = 0;
    int rightSize = 0;

    // Populate the enlarged array with these new roots.
    newTable[i] = leftSize > 0 ? leftBuilder.root() : null;
    newTable[i + oldCapacity] = rightSize > 0 ? rightBuilder.root() : null;
  }
}

static class AvlIterator<K, V> {
    /** This stack is a singly linked list, linked by the 'parent' field. */
    private Node<K, V> stackTop;

    void reset(Node<K, V> root) {
      Node<K, V> stackTop = null;
      for (Node<K, V> n = root; n != null; n = n.left) {
        n.parent = stackTop;
        stackTop = n; // Stack push.
      }
      this.stackTop = stackTop;
    }

    public Node<K, V> next() {
      Node<K, V> stackTop = this.stackTop;
      if (stackTop == null) {
        return null;
      }
      Node<K, V> result = stackTop;
      stackTop = result.parent;
      result.parent = null;
      for (Node<K, V> n = result.right; n != null; n = n.left) {
        n.parent = stackTop;
        stackTop = n; // Stack push.
      }
      this.stackTop = stackTop;
      return result;
    }
  }

void reset(int targetSize) {
  // compute the target tree size. This is a power of 2 minus one, like 15 or 31.
  int treeCapacity = Integer.highestOneBit(targetSize) * 2 - 1;
  leavesToSkip = treeCapacity - targetSize;
}

void add(Node<K, V> node) {
  node.left = node.parent = node.right = null;
  node.height = 1;

  // Skip a leaf if necessary.
  if (leavesToSkip > 0 && (size & 1) == 0) {
    size++;
    leavesToSkip--;
    leavesSkipped++;
  }
}

void add(Node<K, V> node) {
  node.parent = stack;
  stack = node;
  size++;

  for (int scale = 4; (size & scale - 1) == scale - 1; scale *= 2) {
    if (leavesSkipped == 0) {
      // Pop right, center and left, then make center the top of the stack.
      Node<K, V> right = stack;
      Node<K, V> center = right.parent;
      Node<K, V> left = center.parent;
      center.parent = left.parent;
      stack = center;
    }
  }
}

void add(Node<K, V> node) {
  node.parent = stack;
  stack = node;
  size++;

  for (int scale = 4; (size & scale - 1) == scale - 1; scale *= 2) {
    if (leavesSkipped == 0) {
      Node<K, V> right = stack;
      Node<K, V> center = right.parent;
      Node<K, V> left = center.parent;
      center.parent = left.parent;
      stack = center;

      // Construct a tree.
      center.left = left;
      center.right = right;
      center.height = right.height + 1;
      left.parent = center;
      right.parent = center;
    }
  }
}

void add(Node<K, V> node) {
  node.parent = stack;
  stack = node;
  size++;

  for (int scale = 4; (size & scale - 1) == scale - 1; scale *= 2) {
    if (leavesSkipped == 1) {
      // Pop right and center, then make center the top of the stack.
      Node<K, V> right = stack;
      Node<K, V> center = right.parent;
      stack = center;
    }
  }
}

void add(Node<K, V> node) {
  node.parent = stack;
  stack = node;
  size++;

  for (int scale = 4; (size & scale - 1) == scale - 1; scale *= 2) {
    if (leavesSkipped == 1) {
      Node<K, V> right = stack;
      Node<K, V> center = right.parent;
      stack = center;

      // Construct a tree with no left child.
      center.right = right;
      center.height = right.height + 1;
      right.parent = center;

      leavesSkipped = 0;
    }
  }
}

