            K leastUsed = this.queue.poll();
            if (leastUsed != null) {
                this.cache.remove(leastUsed);
            }
        }
        this.queue.offer(key);
        this.cache.put(key, value);
        this.size = this.cache.size();
        return value;
    }
    finally {
        this.lock.writeLock().unlock();
    }
}

