def scroll_to(self, widget, padding=10, animate=True):
        '''Scrolls the viewport to ensure that the given widget is visible,
        optionally with padding and animation. If animate is True (the
        default), then the default animation parameters will be used.
        Otherwise, it should be a dict containing arguments to pass to
        :class:`~kivy.animation.Animation` constructor.

        .. versionadded:: 1.9.1
        '''
        if not self.parent:
            return

        # if _viewport is layout and has pending operation, reschedule
        if hasattr(self._viewport, 'do_layout'):
            if self._viewport._trigger_layout.is_triggered:
                Clock.schedule_once(
                     lambda *dt: self.scroll_to(widget, padding, animate))
                return

        if isinstance(padding, (int, float)):
            padding = (padding, padding)

        pos = self.parent.to_widget(*widget.to_window(*widget.pos))
        cor = self.parent.to_widget(*widget.to_window(widget.right,
                                                      widget.top))

        dx = dy = 0

        if pos[1] < self.y:
            dy = self.y - pos[1] + dp(padding[1])
        elif cor[1] > self.top:
            dy = self.top - cor[1] - dp(padding[1])

        if pos[0] < self.x:
            dx = self.x - pos[0] + dp(padding[0])
        elif cor[0] > self.right:
            dx = self.right - cor[0] - dp(padding[0])

        dsx, dsy = self.convert_distance_to_scroll(dx, dy)
        sxp = min(1, max(0, self.scroll_x - dsx))
        syp = min(1, max(0, self.scroll_y - dsy))

        if animate:
            if animate is True:
                animate = {'d': 0.2, 't': 'out_quad'}
            Animation.stop_all(self, 'scroll_x', 'scroll_y')
            Animation(scroll_x=sxp, scroll_y=syp, **animate).start(self)
        else:
            self.scroll_x = sxp
            self.scroll_y = syp

def filter(self, **kwargs):
    kwargs_get = kwargs.get

    priority = kwargs_get('priority', None)
    min_p, max_p = None, None
    if priority is not None:
        if isinstance(priority, list):
            min_p, max_p = priority
        elif isinstance(priority, int):
            min_p, max_p = None, priority

    # Prepare a correctly sorted tasklist
    force_priority_sort = kwargs.get('force_priority_sort', None)
    force_sort_on = force_priority_sort and True
    force_sort_off = (force_priority_sort is False) and True

    db = kwargs.get('db', None) or self.db
    if (force_sort_on or priority) and not force_sort_off:
        tasklist = sorted(db, key=lambda n: n.priority)
    else:
        tasklist = db

def filter(self, **kwargs):
    out = deque()
    if not have_filters:
        out.extend(tasklist)
        return out

    # Now test each gesture in the database against filter criteria
    out_append = out.append
    for gesture in tasklist:

        if (orientation_sens is not None and
                orientation_sens != gesture.orientation_sens):
            continue

        if numpoints and gesture.numpoints not in numpoints:
            continue

        if numstrokes and len(gesture.strokes) not in numstrokes:
            continue

        if min_p is not None and gesture.priority < min_p:
            continue

        if max_p is not None and gesture.priority > max_p:
            return out

        if name:
            for f in name:
                if re_match(f, gesture.name):
                    out_append(gesture)
                    break
        else:
            out_append(gesture)

    return out

def recognize(self, strokes, goodscore=None, timeout=0, delay=0, **kwargs):
    def _recognize_tick(dt):
        # The loop has ended. Prepare to dispatch 'complete'
        def _dispatch():
            result.dispatch('on_complete')
            self.dispatch('on_search_complete', result)
            return False

        # Dispatch or reschedule another run
        if not tasklist:
            result.status = 'complete'
            return _dispatch()
        elif result._break_flag:
            result.status = 'stop'
            return _dispatch()
        elif stop_now:
            return _dispatch()
        else:
            Clock.schedule_once(_recognize_tick, delay)
            return True

